package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class DoctorService{private final DoctorRepository r;private final DepartmentRepository dr;private final HospitalRepository hr;public DoctorService(DoctorRepository r,DepartmentRepository dr,HospitalRepository hr){this.r=r;this.dr=dr;this.hr=hr;} private Doctor find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Doctor not found"));} private DoctorDTO dto(Doctor e){return DoctorDTO.builder().id(e.getId()).name(e.getName()).email(e.getEmail()).phoneNumber(e.getPhoneNumber()).specialization(e.getSpecialization()).departmentId(e.getDepartment().getId()).hospitalId(e.getHospital().getId()).build();} private void apply(Doctor e,DoctorDTO d){Department dep=dr.findById(d.getDepartmentId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Department not found"));Hospital h=hr.findById(d.getHospitalId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Hospital not found"));e.setName(d.getName());e.setEmail(d.getEmail());e.setPhoneNumber(d.getPhoneNumber());e.setSpecialization(d.getSpecialization());e.setDepartment(dep);e.setHospital(h);} public DoctorDTO create(DoctorDTO d){Doctor e=new Doctor();apply(e,d);return dto(r.save(e));} public List<DoctorDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public DoctorDTO get(Long id){return dto(find(id));} public DoctorDTO update(Long id,DoctorDTO d){Doctor e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Doctor e=find(id);e.setIsActive(false);r.save(e);} public List<DoctorDTO> department(Long id){return r.findByDepartmentIdAndIsActiveTrue(id).stream().map(this::dto).toList();}}
